@layer components {
  .feed-page {
    max-width: var(--shelf-feedpage-maxWidth);
  }

  .feed-page-heading {
    color: var(--shelf-feedpage-fgColor-heading);
    font-size: var(--shelf-feedpage-fontSize-heading);
  }

  .feed-page-list {
    display: flex;
    flex-direction: column;
    gap: var(--shelf-feedpage-space-gap);
    list-style: none;
  }

  .feed-item {
    background-color: var(--shelf-feedpage-bgColor-card);
    border-color: var(--shelf-feedpage-borderColor-card);
    border-style: solid;
    border-width: var(--shelf-feedpage-borderWidth-card);
    border-radius: var(--shelf-feedpage-radius-card);
    padding: var(--shelf-feedpage-space-padding);
  }

  .feed-item-title {
    color: var(--shelf-feedpage-fgColor-title);
    font-size: var(--shelf-feedpage-fontSize-title);
  }

  .feed-item-description {
    color: var(--shelf-feedpage-fgColor-description);
    font-size: var(--shelf-feedpage-fontSize-description);
  }
}
